(function(global){
  'use strict';
  var H=global.GuaHero;
  var esc=value=>String(value==null?'':value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function lines(values,width,step,thick){return values.slice().reverse().map((n,i)=>n?`<rect y="${i*step}" width="${width}" height="${thick}"/>`:`<rect y="${i*step}" width="${width*.4}" height="${thick}"/><rect x="${width*.6}" y="${i*step}" width="${width*.4}" height="${thick}"/>`).join('');}
  H.register('E',function(ctx){
    var ring=ctx.hexagrams.map((h,i)=>{var a=i*360/64-90,r=a*Math.PI/180;return `<g data-ring-id="${h.number}" data-lines-bottom-up="${h.lines.join('')}" transform="translate(${(300+252*Math.cos(r)).toFixed(3)} ${(300+252*Math.sin(r)).toFixed(3)}) rotate(${a+90}) translate(-7 -8)" fill="${h.number===ctx.id?'#a44232':'#88917c'}">${lines(h.lines,14,2.9,1.05)}</g>`;}).join('');
    var legend=['乾','兌','離','震','坤','艮','坎','巽'].map(name=>ctx.trigrams.find(t=>t.chineseName===name)).map(t=>`<li><b>${esc(t.chineseName)}</b>${esc(t.chineseImage)}</li>`).join('');
    return `<figure class="concept-e" data-hero-layout="E" data-hexagram="${ctx.id}"><div class="concept-e-orbit"><svg viewBox="0 0 600 600" role="img" aria-label="六十四卦環，中央為第${ctx.id}卦${esc(ctx.name)}，上${esc(ctx.top.chineseName)}下${esc(ctx.bottom.chineseName)}"><defs><radialGradient id="e-glow"><stop offset="0" stop-color="#e6e9d6" stop-opacity=".7"/><stop offset="1" stop-color="#f5f1e8" stop-opacity="0"/></radialGradient></defs><circle cx="300" cy="300" r="222" fill="url(#e-glow)"/><g fill="none" stroke="#c1c7b4" stroke-width=".8"><circle cx="300" cy="300" r="277"/><circle cx="300" cy="300" r="229"/><path d="M300 12v20M300 568v20M12 300h20M568 300h20"/></g>${ring}<g data-central-id="${ctx.id}" data-lines-bottom-up="${ctx.hexagram.lines.join('')}" fill="#283830" transform="translate(244 207)">${lines(ctx.hexagram.lines,112,28,8)}</g><circle cx="300" cy="23" r="3" fill="#a44232"/></svg><span class="concept-e-verse">第 ${ctx.id} 卦 · 上${esc(ctx.top.chineseName)}下${esc(ctx.bottom.chineseName)}</span><strong class="concept-e-center-title">${esc(ctx.name)}</strong></div><figcaption class="concept-e-caption"><span class="concept-e-seal" aria-hidden="true">易</span><div><p>${esc(ctx.quote)}</p><small>六十四種意象<span>·</span>六十四個看見自己的角度</small></div></figcaption><ul class="concept-e-legend" aria-label="八卦與自然意象">${legend}</ul></figure>`;
  });
})(window);
